<script>
const overlay=document.getElementById('overlay'),form=document.getElementById('universityForm'),nameInput=document.getElementById('universityName');let previousFocus=null;
function openDrawer(button){previousFocus=document.activeElement;form.reset();document.getElementById('editId').value='';const editing=!!button;document.getElementById('drawerTitle').textContent=editing?'Edit university':'Add university';document.getElementById('drawerDescription').textContent=editing?'Update this awarding institution. Linked degree programmes will remain attached.':'Create an awarding university to organize its degree programmes.';document.getElementById('saveButton').textContent=editing?'Save changes →':'Create university →';if(editing){document.getElementById('editId').value=button.dataset.id;nameInput.value=button.dataset.name;document.getElementById('universityCode').value=button.dataset.code;}overlay.classList.add('open');document.body.style.overflow='hidden';nameInput.focus();}
function closeDrawer(){overlay.classList.remove('open');document.body.style.overflow='';if(previousFocus)previousFocus.focus();}
document.getElementById('addUniversity').addEventListener('click',()=>openDrawer(null));document.querySelectorAll('.edit').forEach(b=>b.addEventListener('click',()=>openDrawer(b)));document.getElementById('closeDrawer').addEventListener('click',closeDrawer);document.getElementById('cancelDrawer').addEventListener('click',closeDrawer);overlay.addEventListener('click',e=>{if(e.target===overlay)closeDrawer()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay.classList.contains('open'))closeDrawer();});
document.getElementById('universitySearch').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();let visible=0;document.querySelectorAll('.uni').forEach(card=>{const show=card.dataset.search.includes(q);card.classList.toggle('hidden',!show);if(show)visible++});document.getElementById('noMatches').classList.toggle('hidden',visible!==0||document.querySelectorAll('.uni').length===0);});
document.getElementById('themeButton').addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('ulearn-theme',next)});
